// The game-systems parity audit (src/systemsWikiAudit.js): trading, brewing, enchanting, effects, smithing, Java
// commands and redstone against the Minecraft Wiki (src/systemsWikiData.js, generated by
// scripts/generate-systems-wiki-data.mjs). A sweep holds every system at zero failures; sensitivity tests prove each
// check can fail; and the behaviour the audit found missing -- the mace's smash attack and enchantments, the Java
// commands, the buttons and pressure plates -- is exercised directly.
import test from 'node:test';
import assert from 'node:assert/strict';
import {
  systemsAudit, tradeCases, brewingCases, enchantingCases, effectCases, smithingCases, commandCases, redstoneCases,
  newerThanTarget, COMMANDS_WITHOUT_A_SYSTEM,
} from '../src/systemsWikiAudit.js';
import { WIKI_TRADES, WIKI_BREWING, WIKI_ENCHANTMENTS, WIKI_EFFECTS, WIKI_SMITHING, WIKI_COMMANDS, WIKI_REDSTONE } from '../src/systemsWikiData.js';
import { POTION_DATA, getBrewingResult } from '../src/brewing.js';
import { ENCHANTMENT_REGISTRY, eligibleEnchantments, anvilAccepts } from '../src/enchanting.js';
import { EFFECTS } from '../src/statusEffects.js';
import { PROFESSION_TRADES } from '../src/villagerEconomy.js';
import { canSmash, smashBonus, breachedArmourFraction, windBurstHeight, windBurstVelocity } from '../src/maceSmash.js';
import { runCommand, buildCommandContext } from '../src/commandRunner.js';
import { BLOCKS, BLOCK_DEFS } from '../src/blocks.js';
import { BUTTON_HOLD, PLATE_KIND, plateSignal, containerSignal } from '../src/redstoneComponents.js';
import { parityCasesForEntry, parityAuditEverything } from '../src/resourceParityCases.js';
import { cellForName } from '../src/wikiNames.js';

const failuresOf = (rows) => rows.filter((r) => r.status === 'FAIL').map((r) => `${r.id} ${r.label}: wiki ${r.expected}, game ${r.actual}`);

// --- the data ------------------------------------------------------------------------------------------------

test('the wiki data covers every system, Java Edition only', () => {
  assert.ok(WIKI_TRADES.length >= 280, `trades: ${WIKI_TRADES.length}`);
  assert.equal(WIKI_TRADES.filter((t) => t.trader === 'wandering_trader').length > 0, true);
  assert.ok(WIKI_BREWING.length >= 22, 'every potion row');
  assert.ok(WIKI_ENCHANTMENTS.length >= 40);
  assert.equal(WIKI_ENCHANTMENTS.some((e) => e.id === 'cleaving'), false, 'Combat Test enchantments are left out');
  assert.ok(WIKI_EFFECTS.length >= 39);
  assert.equal(WIKI_SMITHING.templates.length, 18);
  assert.equal(WIKI_SMITHING.materials.length, 11);
  assert.ok(WIKI_COMMANDS.length >= 90);
  assert.ok(Object.keys(WIKI_REDSTONE).length >= 18);
  // Every redstone fact keeps the sentence it was read from.
  for (const [key, fact] of Object.entries(WIKI_REDSTONE)) assert.ok(fact.page && fact.quote, key);
});

test('version labels: what is newer than the 1.21.4 target', () => {
  assert.equal(newerThanTarget('1.21.4'), false);
  assert.equal(newerThanTarget('1.21.2'), false);
  assert.equal(newerThanTarget('1.21.5'), true);
  assert.equal(newerThanTarget('26.1'), true);
  assert.equal(newerThanTarget('v1.0.16'), false, 'an alpha label is old');
});

// --- the sweep -----------------------------------------------------------------------------------------------

test('SWEEP: every system agrees with the wiki', () => {
  const audit = systemsAudit();
  assert.deepEqual(failuresOf(audit.rows), []);
  assert.ok(audit.totals.PASS > 900, `passes: ${audit.totals.PASS}`);
  // The only KNOWN rows are the commands whose system the game does not have, each with its reason.
  const known = audit.rows.filter((r) => r.status === 'KNOWN');
  assert.deepEqual(known.map((r) => r.subject).sort(), Object.keys(COMMANDS_WITHOUT_A_SYSTEM).sort());
  for (const r of known) assert.match(r.note, /^not run: /);
});

test('the systems cases reach the Inspector: per resource and in the full audit', () => {
  // A potion's page shows its brewing, a netherite piece its upgrade, a button its redstone behaviour.
  const potion = parityCasesForEntry({ kind: 'item', id: 'potion_of_turtle_master', blockId: null });
  assert.ok(potion.some((c) => c.id === 'B-BREW' && /Turtle Shell/.test(c.label)), 'the Turtle Master brewing case');
  const sword = parityCasesForEntry({ kind: 'item', id: 'netherite_sword', blockId: null });
  assert.ok(sword.some((c) => c.id === 'M-UPGRADE'));
  const oak = cellForName('Oak Button');
  assert.ok(parityCasesForEntry({ kind: 'block', id: 'oak_button', blockId: oak.id }).some((c) => c.id === 'R-BUTTON'));
  // And "Run full wiki audit" counts them.
  const all = parityAuditEverything();
  for (const id of ['T-TRADE', 'B-BREW', 'E-ITEMS', 'X-EFFECT', 'M-TRIM', 'K-COMMAND', 'R-PLATE']) assert.ok(all.byCase[id], id);
});

// --- each check can fail -------------------------------------------------------------------------------------

function withPatched(object, key, value, run) {
  const had = Object.prototype.hasOwnProperty.call(object, key); const old = object[key];
  object[key] = value;
  try { return run(); } finally { if (had) object[key] = old; else delete object[key]; }
}

test('SENSITIVITY: a wrong trade, potion time, enchantment, effect or command is caught', () => {
  // A farmer who buys melon slices again.
  const melons = PROFESSION_TRADES.farmer.find((r) => r.level === 3 && r.cost?.wikiId === 'melon');
  withPatched(melons.cost, 'id', 'melon_slice', () => withPatched(melons.cost, 'isBlock', false, () => withPatched(melons.cost, 'wikiId', 'melon_slice', () => withPatched(melons.cost, 'name', 'Melon Slice', () => {
    assert.ok(failuresOf(tradeCases()).some((f) => /farmer L3: 4 Melon/.test(f)));
  }))));
  withPatched(POTION_DATA.potion_of_swiftness, 'duration', 170, () => {
    assert.ok(failuresOf(brewingCases()).some((f) => /Potion of Swiftness lasts 3:00/.test(f)));
  });
  withPatched(ENCHANTMENT_REGISTRY.sharpness, 'weight', 5, () => {
    assert.ok(failuresOf(enchantingCases()).some((f) => /Sharpness weight/.test(f)));
  });
  withPatched(EFFECTS.speed, 'category', 'harmful', () => {
    assert.ok(failuresOf(effectCases()).some((f) => /Speed is Positive/.test(f)));
  });
  assert.equal(failuresOf(smithingCases()).length, 0);
  // Without /seed in the table, the Java command is reported missing.
  assert.ok(commandCases().some((r) => r.subject === 'seed' && r.status === 'PASS'));
});

test('SENSITIVITY: the redstone probes measure the engine, so a slower button fails', () => {
  const hold = BUTTON_HOLD.get(BLOCKS.STONE_BUTTON);
  BUTTON_HOLD.set(BLOCKS.STONE_BUTTON, hold - 1);
  try {
    assert.ok(failuresOf(redstoneCases()).some((f) => /Stone Button stays on/.test(f)));
  } finally { BUTTON_HOLD.set(BLOCKS.STONE_BUTTON, hold); }
});

// --- what the audit made the game do ---------------------------------------------------------------------------

test('trading: a farmer buys melons, a mason sells coloured terracotta', () => {
  assert.ok(PROFESSION_TRADES.farmer.some((r) => r.level === 3 && r.cost.wikiId === 'melon' && r.cost.count === 4));
  assert.ok(PROFESSION_TRADES.mason.some((r) => r.level === 4 && r.reward.wikiId === 'white_terracotta'));
});

test('brewing: turtle shell makes Turtle Master; most effect ingredients make a water bottle mundane', () => {
  assert.equal(getBrewingResult('awkward_potion', 'turtle_helmet'), 'potion_of_turtle_master');
  assert.equal(getBrewingResult('water_bottle', 'sugar'), 'mundane_potion');
  assert.equal(getBrewingResult('water_bottle', BLOCKS.STONE), 'mundane_potion', 'a block ingredient, by its numeric id');
  assert.equal(getBrewingResult('water_bottle', 'golden_carrot'), null, 'one of the four exceptions');
});

test('enchanting: the table follows primary items, the anvil also secondary ones; the mace has its three', () => {
  const offered = (id) => eligibleEnchantments(id).map((e) => e.key).sort();
  assert.deepEqual(offered('mace'), ['breach', 'density', 'unbreaking']);
  assert.deepEqual(offered('iron_axe'), ['efficiency', 'fortune', 'silk_touch', 'unbreaking']);
  assert.deepEqual(offered('crossbow'), ['multishot', 'piercing', 'quick_charge', 'unbreaking']);
  assert.equal(offered('iron_boots').includes('thorns'), false, 'Thorns is offered only on a chestplate');
  assert.equal(anvilAccepts(ENCHANTMENT_REGISTRY.thorns, 'iron_boots'), true, 'but an anvil puts it on boots');
  assert.equal(anvilAccepts(ENCHANTMENT_REGISTRY.wind_burst, 'mace'), true);
  assert.equal(anvilAccepts(ENCHANTMENT_REGISTRY.density, 'diamond_sword'), false);
});

test('the mace: a smash after 1.5 blocks, the wiki\'s damage steps, Density, Breach and Wind Burst', () => {
  assert.equal(canSmash({ itemId: 'mace', fallDistance: 1.4 }), false);
  assert.equal(canSmash({ itemId: 'mace', fallDistance: 2 }), true);
  assert.equal(canSmash({ itemId: 'mace', fallDistance: 2, slowFalling: true }), false, 'not with Slow Falling');
  assert.equal(canSmash({ itemId: 'mace', fallDistance: 2, elytraFlying: true }), false, 'not in elytra flight');
  assert.equal(canSmash({ itemId: 'diamond_sword', fallDistance: 9 }), false);
  // "4 extra damage for each of the first 3 blocks fallen, 2 ... for each of the next 5 ... and 1 ... after that".
  assert.equal(smashBonus(1), 0);
  assert.equal(smashBonus(3), 12);
  assert.equal(smashBonus(8), 22);
  assert.equal(smashBonus(10), 24);
  // Density: "0.5 per block fallen per level".
  assert.equal(smashBonus(10, 5), 24 + 25);
  // Breach: "if the enemy's armor reduces damage by 50% ... Breach I ... 50% - 15% = 35%".
  assert.equal(breachedArmourFraction(0.5, 1), 0.35);
  assert.equal(breachedArmourFraction(0.2, 4), 0, 'never below nothing');
  // Wind Burst: "approximately 8 blocks ... for the first level, 16 ... second, and 24 ... third".
  assert.deepEqual([1, 2, 3].map(windBurstHeight), [8, 16, 24]);
  const v = windBurstVelocity(1, 28);
  assert.ok(Math.abs((v * v) / (2 * 28) - 8) < 1e-9, 'the launch speed rises eight blocks');
});

// --- the Java commands ------------------------------------------------------------------------------------------

function fakeGame(overrides = {}) {
  const chat = [];
  const effects = new Map();
  const game = {
    chat, seed: 1234, difficulty: 'normal', worldTime: 0,
    settings: { gameMode: 'creative', cheats: true, difficulty: 'normal' },
    ui: { addChatMessage: (text, kind) => chat.push({ text, kind }), updateHotbar() {}, updateStats() {} },
    player: {
      gamemode: 'creative', position: { x: 0, y: 64, z: 0 }, level: 0, exp: 0, health: 20, statusEffects: effects,
      applyStatusEffect(id, duration, level) { effects.set(id, { duration, level }); },
      clearStatusEffect(id) { effects.delete(id); },
      takeDamage(amount) { this.health -= amount; },
      die() { this.dead = true; },
    },
    inventory: { hotbar: Array(9).fill(null), storage: Array(27).fill(null), activeSlot: 0, getActiveItem() { return this.hotbar[this.activeSlot]; } },
    world: null,
    ...overrides,
  };
  return game;
}
const run = (game, line) => runCommand(buildCommandContext(game), line);
const last = (game) => game.chat[game.chat.length - 1]?.text;

test('/effect, /enchant, /experience and /kill act on the player', () => {
  const g = fakeGame();
  run(g, '/effect give @s minecraft:speed 60 1');
  assert.deepEqual(g.player.statusEffects.get('speed'), { duration: 60, level: 2 });
  run(g, '/effect give @s speed');
  run(g, '/effect clear @s speed');
  assert.equal(g.player.statusEffects.has('speed'), false);
  g.inventory.hotbar[0] = { id: 'mace', isBlock: false, count: 1 };
  run(g, '/enchant @s density 5');
  assert.deepEqual(g.inventory.hotbar[0].enchantments.map((e) => [e.id, e.level]), [['density', 5]]);
  run(g, '/enchant @s breach');
  assert.match(last(g), /cannot be combined/, 'Breach and Density conflict');
  run(g, '/enchant @s sharpness 6');
  assert.match(last(g), /higher than the maximum level of 5/);
  run(g, '/experience add @s 5 levels');
  assert.equal(g.player.level, 5);
  run(g, '/xp query @s levels');
  assert.equal(last(g), 'Player has 5 experience levels');
  run(g, '/kill @s');
  assert.equal(g.player.dead, true);
});

test('/time, /difficulty, /gamerule, /seed, /random and the chat commands', () => {
  const g = fakeGame();
  run(g, '/time set noon'); assert.equal(g.worldTime, 6000);
  run(g, '/difficulty hard'); assert.equal(g.difficulty, 'hard'); assert.equal(g.settings.difficulty, 'hard');
  run(g, '/gamerule keepInventory true'); assert.equal(g.gamerules.keepInventory, true);
  run(g, '/gamerule doDaylightCycle'); assert.equal(last(g), 'Gamerule doDaylightCycle is currently set to: true');
  run(g, '/gamerule noSuchRule true'); assert.match(last(g), /Unknown game rule/);
  run(g, '/seed'); assert.equal(last(g), 'Seed: [1234]');
  run(g, '/random value 1..6'); assert.match(last(g), /^Random value: [1-6]$/);
  run(g, '/say hello'); assert.equal(last(g), '[Player] hello');
  run(g, '/me waves'); assert.equal(last(g), '* Player waves');
  run(g, '/tellraw @s {"text":"hi ","extra":[{"text":"there"}]}'); assert.equal(last(g), 'hi there');
  run(g, '/list'); assert.match(last(g), /There are 1 of a max of 1 players online/);
});

test('/fill and /clone change blocks within the block limit', () => {
  const voxels = new Map();
  const world = { getVoxel: (x, y, z) => voxels.get(`${x},${y},${z}`) ?? 0, setVoxel: (x, y, z, id) => voxels.set(`${x},${y},${z}`, id), getOrCreateChunk: () => null, invalidateChunkCache() {} };
  const g = fakeGame({ world });
  run(g, '/fill 0 0 0 2 2 2 stone');
  assert.equal(last(g), 'Successfully filled 27 block(s)');
  run(g, '/fill 0 0 0 2 2 2 glass hollow');
  assert.equal(world.getVoxel(1, 1, 1), 0, 'hollow empties the inside');
  assert.equal(world.getVoxel(0, 0, 0), BLOCKS.GLASS);
  run(g, '/fill 0 0 0 40 40 40 stone');
  assert.match(last(g), /Too many blocks in the specified area \(maximum 32768, specified 68921\)/);
  run(g, '/clone 0 0 0 2 2 2 10 0 0');
  assert.equal(world.getVoxel(10, 0, 0), BLOCKS.GLASS);
  run(g, '/clone 0 0 0 2 2 2 1 0 0');
  assert.equal(last(g), 'The source and destination can not overlap');
});

test('/spawnpoint sets where the player respawns, /setworldspawn the world\'s', () => {
  const g = fakeGame();
  run(g, '/spawnpoint @s 10 70 -4');
  assert.deepEqual(g.player.commandSpawnPosition, { x: 10.5, y: 70, z: -3.5 });
  run(g, '/setworldspawn 1 65 1');
  assert.deepEqual(g.player.spawnPosition, { x: 1.5, y: 65, z: 1.5 });
});

test('the new commands are cheats in Survival without cheats, except Java\'s level-0 ones', () => {
  const g = fakeGame({ settings: { gameMode: 'survival', cheats: false } });
  g.player.gamemode = 'survival';
  run(g, '/kill');
  assert.match(last(g), /You do not have permission to use \/kill/);
  assert.equal(g.player.dead, undefined);
  run(g, '/seed');
  assert.equal(last(g), 'Seed: [1234]', '/seed is level 0 in single player');
});

// --- redstone components ------------------------------------------------------------------------------------------

test('every button and pressure plate is a redstone component with the wiki\'s behaviour', () => {
  const buttons = Object.entries(BLOCK_DEFS).filter(([, d]) => /Button$/.test(d?.name ?? '')).map(([id]) => Number(id));
  const plates = Object.entries(BLOCK_DEFS).filter(([, d]) => /Pressure Plate$/.test(d?.name ?? '')).map(([id]) => Number(id));
  assert.ok(buttons.length >= 14 && plates.length >= 17);
  for (const id of buttons) { assert.equal(BLOCK_DEFS[id].redstone, true, BLOCK_DEFS[id].name); assert.ok(BUTTON_HOLD.has(id)); }
  for (const id of plates) { assert.equal(BLOCK_DEFS[id].redstone, true, BLOCK_DEFS[id].name); assert.ok(PLATE_KIND.has(id)); }
  assert.equal(BUTTON_HOLD.get(cellForName('Oak Button').id), 15, 'a wooden button: 30 game ticks');
  assert.equal(BUTTON_HOLD.get(cellForName('Polished Blackstone Button').id), 10, 'a stone-type button: 20 game ticks');
  assert.equal(plateSignal('stone', [{ isItem: true }]), 0, 'a stone plate ignores items');
  assert.equal(plateSignal('wood', [{ isItem: true }]), 15, 'a wooden plate does not');
  assert.equal(plateSignal('heavy', Array(25).fill({ isMob: true })), 3);
  // The comparator's container reading: the page's worked example.
  assert.equal(containerSignal([{ id: 'stone', count: 300 }], 9, () => 64), 8);
});
